window.bosses_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

// ── HP bar ─────────────────────────────────────────────────────────
bosses_elements.lib.Hp_bar=class extends e{
  constructor(w,ht){
    super();this._maxW=w;
    const bg=new A();bg.beginFill(0x1a0505,1);bg.drawRoundedRect(0,0,w,ht,3);bg.endFill();
    this.fill=new A();this.fill.beginFill(0xaa1111,1);this.fill.drawRoundedRect(0,0,w,ht,3);this.fill.endFill();
    const brd=new A();brd.lineStyle(1,0x662222,0.8);brd.drawRoundedRect(0,0,w,ht,3);
    this.addChild(bg,this.fill,brd);
    this[this.fill.name='fill']=this.fill;
  }
  setPercent(p){this.fill.scale.x=Math.max(0,Math.min(1,p));}
};

// ── Boss list item ─────────────────────────────────────────────────
bosses_elements.lib.Boss_item=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x0d1a0d,0.85);bg.lineStyle(1,0x2a4a2a,0.8);bg.drawRoundedRect(0,0,248,58,4);bg.endFill();
    const ic=new A();ic.beginFill(0x1a2e1a,1);ic.lineStyle(1,0x3a6a3a);ic.drawRoundedRect(4,5,48,48,3);ic.endFill();
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:13,fontWeight:'bold',fill:'#d4c080'});nt.x=58;nt.y=7;
    const lt=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#7a9a5a'});lt.x=58;lt.y=25;
    const hp=new bosses_elements.lib.Hp_bar(184,6);hp.x=58;hp.y=44;
    const ov=new A();ov.beginFill(0xffffff,0.07);ov.drawRoundedRect(0,0,248,58,4);ov.endFill();ov.alpha=0;
    this[nt.name='name_txt']=nt;this[lt.name='level_txt']=lt;this[hp.name='hp_bar']=hp;this[ov.name='overlay']=ov;
    this.addChild(bg,ic,nt,lt,hp,ov);
    this.interactive=true;this.buttonMode=true;
    this.on('mouseover',()=>ov.alpha=1);this.on('mouseout',()=>ov.alpha=0);
  }
};

// ── Weapon slot ────────────────────────────────────────────────────
bosses_elements.lib.Weapon_slot=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x0d150d,1);bg.lineStyle(1,0x2a4a2a);bg.drawRoundedRect(0,0,58,58,4);bg.endFill();
    const lbl=new z('ПУСТО',{fontFamily:'Arial',fontSize:9,fill:'#3a5a3a',align:'center',wordWrap:true,wordWrapWidth:54});
    lbl.anchor.set(0.5,0.5);lbl.x=29;lbl.y=29;
    this[lbl.name='label_txt']=lbl;
    this.addChild(bg,lbl);
  }
};

// ── Boss detail panel ──────────────────────────────────────────────
bosses_elements.lib.Boss_detail=class extends e{
  constructor(){
    super();
    // Portrait box
    const port=new A();port.beginFill(0x0a150a,1);port.lineStyle(2,0x3a6a3a,0.9);port.drawRoundedRect(0,0,180,180,6);port.endFill();
    const cross=new A();cross.lineStyle(1,0x2a4a2a,0.5);cross.moveTo(90,20);cross.lineTo(90,160);cross.moveTo(20,90);cross.lineTo(160,90);cross.drawCircle(90,90,50);
    this[port.name='portrait']=port;
    // Name
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:22,fontWeight:'bold',fill:'#e8d090',dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});nt.x=196;nt.y=4;
    this[nt.name='name_txt']=nt;
    // Level
    const lt=new z('',{fontFamily:'Southbank LT',fontSize:13,fill:'#7ab05a'});lt.x=196;lt.y=34;
    this[lt.name='level_txt']=lt;
    // HP text
    const hpt=new z('',{fontFamily:'Southbank LT',fontSize:12,fill:'#c07070'});hpt.x=196;hpt.y=58;
    this[hpt.name='hp_txt']=hpt;
    // HP bar
    const hp=new bosses_elements.lib.Hp_bar(580,14);hp.x=196;hp.y=78;
    this[hp.name='hp_bar']=hp;
    // Desc
    const dt=new z('',{fontFamily:'Arial',fontSize:12,fill:'#a0b080',wordWrap:true,wordWrapWidth:580,lineHeight:18});dt.x=196;dt.y=100;
    this[dt.name='desc_txt']=dt;
    // Reward
    const rt=new z('',{fontFamily:'Southbank LT',fontSize:12,fill:'#c8a040',wordWrap:true,wordWrapWidth:580});rt.x=196;rt.y=152;
    this[rt.name='reward_txt']=rt;
    // Weapon section label
    const wlbl=new z('ОРУЖИЕ:',{fontFamily:'Southbank LT',fontSize:11,fill:'#5a7a5a',letterSpacing:2});wlbl.x=2;wlbl.y=190;
    // Weapon slots (3)
    const ws=new e();ws.x=2;ws.y=208;
    for(let i=0;i<3;i++){const sl=new bosses_elements.lib.Weapon_slot();sl.x=i*66;ws['slot_'+i]=sl;ws.addChild(sl);}
    this[ws.name='weapon_slots']=ws;
    // Attack button
    const abg=new A();abg.beginFill(0x8b1515,1);abg.lineStyle(2,0xcc3333,0.9);abg.drawRoundedRect(0,0,200,46,5);abg.endFill();
    const at=new z('АТАКОВАТЬ',{fontFamily:'Southbank LT',fontSize:16,fontWeight:'bold',fill:'#ffdddd',align:'center',dropShadow:true,dropShadowDistance:1,dropShadowColor:'#000'});at.anchor.set(0.5,0.5);at.x=100;at.y=23;
    const ab=new e();ab.addChild(abg,at);ab.x=196;ab.y=278;
    ab.interactive=true;ab.buttonMode=true;
    ab.on('mouseover',()=>abg.tint=0xddaaaa);ab.on('mouseout',()=>abg.tint=0xffffff);
    this[ab.name='butt_attack']=ab;
    this.addChild(port,cross,nt,lt,hpt,hp,dt,rt,wlbl,ws,ab);
  }
};

// ── Main window ────────────────────────────────────────────────────
bosses_elements.lib.Bosses_win=class extends e{
  constructor(){
    super();
    // Window bg
    const wb=new A();wb.beginFill(0x060e06,0.97);wb.lineStyle(2,0x2a5a2a,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();
    this.addChild(wb);
    // Header bg
    const hb=new A();hb.beginFill(0x0d200d,1);hb.drawRect(2,2,1196,44);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x2a5a2a,0.5);hl.moveTo(2,47);hl.lineTo(1198,47);
    this.addChild(hb,hl);
    // Title
    const ttl=new z('БОССЫ',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#d4c070',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});
    ttl.x=20;ttl.y=12;this.addChild(ttl);
    // Close btn
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cb=new e();cb.addChild(cbg,ctx);cb.x=1162;cb.y=8;
    cb.interactive=true;cb.buttonMode=true;
    cb.on('mouseover',()=>cbg.tint=0xddaaaa);cb.on('mouseout',()=>cbg.tint=0xffffff);
    this[cb.name='butt_close']=cb;this.addChild(cb);
    // Sidebar divider
    const div=new A();div.lineStyle(1,0x2a4a2a,0.5);div.moveTo(270,48);div.lineTo(270,520);
    this.addChild(div);
    // Boss list
    const bl=new e();bl.x=10;bl.y=52;
    for(let i=0;i<8;i++){const bi=new bosses_elements.lib.Boss_item();bi.y=i*64;bl['item_'+i]=bi;bl.addChild(bi);}
    this[bl.name='boss_list']=bl;this.addChild(bl);
    // Detail panel
    const det=new bosses_elements.lib.Boss_detail();det.x=280;det.y=52;
    this[det.name='boss_detail']=det;this.addChild(det);
  }
};

// ── Root MovieClip ─────────────────────────────────────────────────
bosses_elements.lib.bosses_elements=class extends n{
  constructor(){
    super({duration:1,framerate:30});
    const b=new bosses_elements.lib.Bosses_win();
    this[b.name='bosses_win']=b;this.addChild(b);
  }
};
bosses_elements.stage=bosses_elements.lib.bosses_elements}};
